    skip_ws(&mut i);
    if i < n && chars[i] == ']' {
        i += 1;
        skip_ws(&mut i);
        return if i == n { Some(out) } else { None };
    }
    loop {
        skip_ws(&mut i);
        if i >= n || chars[i] != '"' {
            return None;
        }
        i += 1;
        let mut cur = String::new();
        loop {
            if i >= n {
                return None;
            }
            let c = chars[i];
            i += 1;
            match c {
                '"' => break,
                '\\' => {
                    if i >= n {
                        return None;
                    }
                    let e = chars[i];
                    i += 1;
                    match e {
                        '"' => cur.push('"'),
                        '\\' => cur.push('\\'),
                        '/' => cur.push('/'),
                        'b' => cur.push('\u{8}'),
                        'f' => cur.push('\u{c}'),
                        'n' => cur.push('\n'),
                        'r' => cur.push('\r'),
                        't' => cur.push('\t'),
                        'u' => {
                            if i + 4 > n {
                                return None;
                            }
