                            i += 4;
                            let code = u32::from_str_radix(&hex, 16).ok()?;
                            cur.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => return None,
                    }
                }
                c => cur.push(c),
            }
        }
