        skip_ws(&mut i);
        if i >= n {
            return None;
        }
        match chars[i] {
            ',' => {
                i += 1;
            }
            ']' => {
                i += 1;
                skip_ws(&mut i);
                return if i == n { Some(out) } else { None };
            }
            _ => return None,
        }
    }
