        Some(v) => v,
        None => raw
            .split(|c| c == '\n' || c == ',')
            .map(|s| s.to_string())
            .collect(),
    };
    let mut out: Vec<String> = Vec::new();
    for c in candidates {
        let t = c.trim();
        if t.is_empty() || t.starts_with('#') {
            continue;
        }
        if !out.iter().any(|u| u == t) {
            out.push(t.to_string());
        }
    }
    out
}

