    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment call (approved grant extension). The result is
        // intentionally discarded: the node's output must not change, and a
        // transport failure is tolerated rather than failing the run.
        let enrich_url = format!("{}{}", ENRICH_BASE, percent_encode(&info.date));
        let _ = http_client::fetch(&enrich_url);

        let mut urls = Vec::new();
        for key in CANDIDATE_KEYS {
            if let Some(raw) = state_read::get(key) {
                let parsed = parse_urls(&raw);
                if !parsed.is_empty() {
                    urls = parsed;
                    break;
                }
            }
        }

        SubscriptionList { urls }
    }
}

export!(Node);
